using System.Text.RegularExpressions;
namespace LSE.AutoCADElectrical.Librarian;
public static class RuleCheckService{
 public static List<(Severity Severity,string Message)> Check(KindRule r,DrawingInfo d){var x=new List<(Severity,string)>();if(d.EntityCount==0)x.Add((Severity.Error,"The drawing's model space is empty."));
  foreach(string spec in r.RequiredAttributes){var options=spec.Split('|',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries);if(!options.Any(d.HasAttribute))x.Add((Severity.Error,"Missing required attribute "+string.Join(" or ",options)+"."));}
  foreach(string spec in r.RecommendedAttributes){var options=spec.Split('|',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries);if(!options.Any(d.HasAttribute))x.Add((Severity.Warning,"Missing recommended attribute "+string.Join(" or ",options)+"."));}
  foreach(string p in r.RequiredAttributePatterns)if(!d.Attributes.Any(a=>Regex.IsMatch(a.Tag,p,RegexOptions.IgnoreCase)))x.Add((Severity.Error,"No attribute matches the required pattern "+p+"."));
  foreach(string p in r.RecommendedAttributePatterns)if(!d.Attributes.Any(a=>Regex.IsMatch(a.Tag,p,RegexOptions.IgnoreCase)))x.Add((Severity.Warning,"No attribute matches the recommended pattern "+p+" (wire connection points such as X1TERM01)."));
  foreach(string b in r.ForbiddenBlocks)if(d.BlockReferences.Any(n=>n.Equals(b,StringComparison.OrdinalIgnoreCase)))x.Add((Severity.Error,"Contains the "+b+" block. Library drawings must not carry drawing-settings blocks; erase it and purge before filing."));
  var dup=d.Attributes.GroupBy(a=>a.Tag,StringComparer.OrdinalIgnoreCase).Where(g=>g.Count()>1).Select(g=>g.Key).ToList();if(dup.Count>0)x.Add((Severity.Warning,"Duplicate attribute tags: "+string.Join(", ",dup)+"."));
  return x;}
}
public static class LibraryAuditService{
 public static AuditReport Run(AppSettings s,LibraryStandard std,AuditOptions o,Action<string>? progress=null){var rep=new AuditReport();void Say(string m){rep.Summary.Add(m);progress?.Invoke(m);}Say($"Audit started {rep.Started:s} by {Environment.UserName}@{Environment.MachineName}{(o.Deep?" (deep: every drawing is opened)":"")}");
  var referenced=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var images=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
  AuditMenu(rep,s,std,o,s.SchematicMenuPath,std.Kinds.Values.Where(k=>!k.IsPanel).ToList(),referenced,images,Say);AuditMenu(rep,s,std,o,s.PanelMenuPath,std.Kinds.Values.Where(k=>k.IsPanel).ToList(),referenced,images,Say);
  var lookup=AuditLookup(rep,s,Say);AuditCatalogMapping(rep,s,Say);
  AuditFolder(rep,s,std,o,LibraryKind.SchematicSymbol,s.SymbolLibraryFolder,referenced,lookup,Say);AuditFolder(rep,s,std,o,LibraryKind.PanelFootprint,s.FootprintLibraryFolder,referenced,lookup,Say);AuditFolder(rep,s,std,o,LibraryKind.UserCircuit,s.UserCircuitsFolder,referenced,lookup,Say);
  AuditImages(rep,s,images,Say);Say($"Findings: {rep.Errors} error(s), {rep.Warnings} warning(s), {rep.Infos} note(s)");return rep;}
 static void Add(AuditReport rep,Severity sev,string area,string kind,string path,string message,string suggestion)=>rep.Findings.Add(new AuditFinding{Severity=sev,Area=area,Kind=kind,Path=path,Message=message,Suggestion=suggestion});
 static void AuditMenu(AuditReport rep,AppSettings s,LibraryStandard std,AuditOptions o,string menuPath,List<KindRule> rules,HashSet<string> referenced,HashSet<string> images,Action<string> say){string file=Path.GetFileName(menuPath);if(!File.Exists(menuPath)){Add(rep,Severity.Error,"Menu","",menuPath,"Icon menu file is missing.","Check LSELIBRARYSETTINGS and the project's +[2]/+[4] lines.");return;}
  IconMenu menu;try{menu=IconMenuService.Load(menuPath);}catch(Exception ex){Add(rep,Severity.Error,"Menu","",menuPath,"Icon menu could not be parsed: "+ex.Message,"Restore the file from a backup.");return;}
  var roots=rules.SelectMany(r=>r.MenuRootPages).Distinct(StringComparer.OrdinalIgnoreCase).ToList();foreach(string root in roots)if(menu.Page(root) is null)Add(rep,Severity.Error,"Menu","",menuPath,$"LSE root page {root} named in the library standard does not exist in {file}.","Create the page or correct menuRootPages in the JSON.");
  var lsePages=IconMenuService.Reachable(menu,roots);var fromMain=IconMenuService.Reachable(menu,new[]{"M0"});var crumbs=IconMenuService.Breadcrumbs(menu);
  foreach(var dup in menu.Pages.GroupBy(p=>p.Id,StringComparer.OrdinalIgnoreCase).Where(g=>g.Count()>1))Add(rep,Severity.Error,"Menu","",menuPath,$"Page {dup.Key} is defined {dup.Count()} times in {file}.","Merge or renumber the duplicate pages.");
  foreach(var p in menu.Pages)if(!fromMain.Contains(p.Id))Add(rep,Severity.Info,"Menu","",menuPath+" **"+p.Id,$"Page {p.Id} ({p.Title}) is not reachable from the main menu M0.","Link it from a parent page with $S="+p.Id+" or remove it.");
  int entries=0;foreach(var page in menu.Pages){bool lse=lsePages.Contains(page.Id);if(!lse&&!o.IncludeStockEntries)continue;string where=$"{file} **{page.Id} ({crumbs.GetValueOrDefault(page.Id,page.Title)})";
   var labels=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var actions=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
   foreach(var e in page.Entries){if(!e.IsEntry)continue;entries++;string at=where+" : "+e.Label;if(e.Label.Trim().Length==0)Add(rep,Severity.Warning,"Menu","",at,"Entry has an empty label.","Give the entry a label.");else if(!labels.Add(e.Label.Trim()))Add(rep,Severity.Warning,"Menu","",at,"Duplicate label on the same page.","Rename one of the entries.");
    string? img=IconMenuService.ResolveImage(menu,e.Image);if(img is not null){images.Add(Path.GetFullPath(img));if(!File.Exists(img))Add(rep,Severity.Error,"Menu","",at,"Icon image is missing: "+e.Image,"Re-create the image with the Librarian (reuse an existing image) or fix the path.");}else if(e.Image.Trim().Length==0)Add(rep,Severity.Info,"Menu","",at,"Entry has no icon image.","Optional: add an image.");
    var t=IconMenuService.ResolveAction(e.Action);if(e.Action.Trim().Length>0&&!actions.Add(e.Action.Trim()))Add(rep,Severity.Info,"Menu","",at,"The same action appears more than once on this page.","Remove the duplicate.");
    switch(t.Kind){case "Submenu":if(menu.Page(t.Path) is null)Add(rep,Severity.Error,"Menu","",at,"Submenu link points to a page that does not exist: "+t.Path,"Fix the $S= target or remove the entry.");break;
     case "Path":case "Command":if(t.Path.Length==0)break;string full;try{full=Path.GetFullPath(t.Path);}catch{Add(rep,Severity.Error,"Menu","",at,"Action contains an invalid path: "+t.Path,"Correct the entry.");break;}
      if(!File.Exists(full)){Add(rep,Severity.Error,"Menu","",at,"Entry points to a drawing that does not exist: "+t.Path,"Restore the drawing or remove the entry.");break;}referenced.Add(full);
      LibraryKind? kind=NamingService.KindFor(s,full);bool stock=NamingService.Inside(full,s.StockSymbolLibraryFolder)||NamingService.Inside(full,s.StockFootprintLibraryFolder);
      if(kind is null&&!stock)Add(rep,Severity.Warning,"Menu",kind?.ToString()??"",at,"Entry points to a drawing outside every configured library folder: "+full,"File it with LSELIBRARIAN so it lives in the library, then point the entry at the library copy.");
      if(kind is not null){var rule=std.Rule(kind.Value);bool panelMenu=s.PanelMenuPath.Equals(menuPath,StringComparison.OrdinalIgnoreCase);if(rule.IsPanel!=panelMenu)Add(rep,Severity.Warning,"Menu",kind.ToString()!,at,$"A {rule.DisplayName.ToLowerInvariant()} is listed in the {(panelMenu?"panel":"schematic")} icon menu.","Move the entry to the other menu.");string name=Path.GetFileNameWithoutExtension(full);var problems=NamingService.Validate(rule,name);if(problems.Count>0)Add(rep,Severity.Warning,"Menu",kind.ToString()!,full,"File name does not follow the LSE standard: "+problems[^1],"Re-file under a standard name with LSELIBRARIAN and retire the old file.");}
      break;
     case "Block":if(lse){bool found=new[]{s.SymbolLibraryFolder,s.StockSymbolLibraryFolder,s.FootprintLibraryFolder,s.StockFootprintLibraryFolder}.Where(f=>f.Length>0&&Directory.Exists(f)).Any(f=>LibraryTransactionService.FindByName(f,t.BlockName+".dwg",std) is not null);if(!found)Add(rep,Severity.Warning,"Menu","",at,"Block name "+t.BlockName+" was not found in any configured library folder.","AutoCAD Electrical may still find it on its own search path; otherwise fix the entry.");}break;}}
   if(!page.Entries.Any(e=>e.IsEntry)&&lse)Add(rep,Severity.Info,"Menu","",where,"Page has no entries.","Add entries or remove the page and its link.");}
  say($"{file}: {menu.Pages.Count} pages, {entries} entries checked ({lsePages.Count} LSE pages)");}
 static List<(string Table,string Catalog,string BlkNam)> AuditLookup(AuditReport rep,AppSettings s,Action<string> say){var rows=new List<(string,string,string)>();if(s.FootprintLookupPath.Length==0||!File.Exists(s.FootprintLookupPath)){Add(rep,Severity.Warning,"Lookup","",s.FootprintLookupPath,"footprint_lookup.mdb was not found; lookup rows were not checked.","Set the path in LSELIBRARYSETTINGS.");return rows;}
  try{rows=new FootprintLookupService(s.FootprintLookupPath).ReadAllPaths();}catch(Exception ex){Add(rep,Severity.Warning,"Lookup","",s.FootprintLookupPath,"footprint_lookup.mdb could not be read: "+ex.Message,"Install the 64-bit Access Database Engine or check the path.");return rows;}
  int missing=0;foreach(var (table,catalog,blk) in rows){if(!(blk.Contains('\\')||blk.Contains('/')))continue;if(!File.Exists(blk)){missing++;Add(rep,Severity.Error,"Lookup","PanelFootprint",$"[{table}] {catalog}","Lookup row points to a missing footprint drawing: "+blk,"Re-file the footprint with LSELIBRARIAN (register lookup) or delete the row.");}}
  say($"footprint_lookup.mdb: {rows.Count} rows with a BLKNAM, {missing} missing drawing(s)");return rows;}
 // LSE parts in default_cat.mdb with no plain footprint_lookup.mdb row, one note per family table. Read only; LSEFOOTPRINTMAP is the fix.
 static void AuditCatalogMapping(AuditReport rep,AppSettings s,Action<string> say){if(s.CatalogPath.Length==0||!File.Exists(s.CatalogPath)||s.FootprintLookupPath.Length==0||!File.Exists(s.FootprintLookupPath))return;
  List<FootprintMapRow> rows;try{rows=FootprintMappingService.Load(s);}catch(Exception ex){Add(rep,Severity.Warning,"Lookup","",s.CatalogPath,"Catalog parts could not be matched to footprint_lookup.mdb: "+ex.Message,"Install the 64-bit Access Database Engine or check the paths.");return;}
  foreach(var g in rows.Where(r=>r.Status==FootprintMappingService.Unmapped).GroupBy(r=>r.Family,StringComparer.OrdinalIgnoreCase).OrderBy(g=>g.Key,StringComparer.OrdinalIgnoreCase)){int total=rows.Count(r=>r.Family.Equals(g.Key,StringComparison.OrdinalIgnoreCase));string sample=string.Join("; ",g.Take(3).Select(r=>r.Manufacturer+" "+r.Catalog));Add(rep,Severity.Info,"Lookup","PanelFootprint","default_cat.mdb ["+g.Key+"]",$"{g.Count()} of {total} LSE part(s) in family table {g.Key} have no footprint_lookup.mdb row (for example {sample}). Panel layout cannot place their footprint from the catalog number.","Run LSEFOOTPRINTMAP, filter on Unmapped and map each part to its footprint drawing. Parts that never go on a panel (wire, markers, software) can be left alone.");}
  say($"Catalog parts: {rows.Count} LSE part(s), {rows.Count(r=>r.Status==FootprintMappingService.Unmapped)} without a footprint lookup row, {rows.Count(r=>r.Status==FootprintMappingService.MissingDrawing)} mapped to a missing drawing");}
 static void AuditFolder(AuditReport rep,AppSettings s,LibraryStandard std,AuditOptions o,LibraryKind kind,string root,HashSet<string> referenced,List<(string Table,string Catalog,string BlkNam)> lookup,Action<string> say){var rule=std.Rule(kind);if(root.Length==0||!Directory.Exists(root)){Add(rep,Severity.Error,"Library",kind.ToString(),root,rule.DisplayName+" library folder is missing.","Set it in LSELIBRARYSETTINGS.");return;}
  var lookupPaths=new HashSet<string>(lookup.Select(r=>{try{return Path.GetFullPath(r.BlkNam);}catch{return r.BlkNam;}}),StringComparer.OrdinalIgnoreCase);var names=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);int count=0,deep=0;
  foreach(string f in LibraryTransactionService.EnumerateDrawings(root,std)){count++;string full=Path.GetFullPath(f);string name=Path.GetFileNameWithoutExtension(f);LibraryKind k=kind==LibraryKind.PanelFootprint&&name.StartsWith("NP_",StringComparison.OrdinalIgnoreCase)?LibraryKind.Nameplate:kind;var r=std.Rule(k);
   if(names.TryGetValue(name,out var other))Add(rep,Severity.Error,"Library",k.ToString(),full,"Duplicate drawing name; AutoCAD Electrical resolves blocks by name so only one can win: "+other,"Keep one copy and update the icon menu entries.");else names[name]=full;
   var problems=NamingService.Validate(r,name);if(problems.Count>0)Add(rep,Severity.Warning,"Library",k.ToString(),full,"File name does not follow the LSE standard: "+problems[^1],"Re-file under a standard name with LSELIBRARIAN and retire the old file.");
   if(k is LibraryKind.PanelFootprint or LibraryKind.Nameplate){string rel=NamingService.Relative(full,root);string folder=rel.Contains('\\')?rel[..rel.IndexOf('\\')]:"";if(folder.Length==0)Add(rep,Severity.Warning,"Library",k.ToString(),full,"Footprint sits in the library root instead of a category folder.","Move it into a category folder (re-file with LSELIBRARIAN).");else if(!r.Categories.Any(c=>c.Folder.Equals(folder,StringComparison.OrdinalIgnoreCase)))Add(rep,Severity.Warning,"Library",k.ToString(),full,"Category folder is not in the library standard: "+folder,"Move the drawing into a standard category folder or add the folder to the JSON.");}
   if(kind==LibraryKind.SchematicSymbol&&s.StockSymbolLibraryFolder.Length>0&&Directory.Exists(s.StockSymbolLibraryFolder)&&File.Exists(Path.Combine(s.StockSymbolLibraryFolder,name+".dwg")))Add(rep,Severity.Warning,"Library",k.ToString(),full,"Name clashes with a stock AutoCAD Electrical symbol of the same name.","Rename the LSE symbol.");
   if(!referenced.Contains(full))Add(rep,Severity.Warning,"Library",k.ToString(),full,"Drawing is not referenced by any icon menu entry.","Register it with LSELIBRARYAUDIT > Open in Librarian (it stays in place) or delete it if obsolete.");
   if(k is LibraryKind.PanelFootprint or LibraryKind.Nameplate&&lookup.Count>0&&!lookupPaths.Contains(full))Add(rep,Severity.Info,"Library",k.ToString(),full,"No footprint_lookup.mdb row points at this drawing (icon-menu insertion still works; catalog-driven insertion does not).","Register it with LSELIBRARIAN if a catalog number should resolve to it.");
   if(o.Deep){deep++;try{var d=DrawingInspectionService.Inspect(full);foreach(var (sev,msg) in RuleCheckService.Check(r,d))Add(rep,sev,"Drawing",k.ToString(),full,msg,sev==Severity.Error?"Open the drawing, fix it and save.":"Optional: open the drawing and add the attribute.");}catch(Exception ex){Add(rep,Severity.Error,"Drawing",k.ToString(),full,"Drawing could not be opened: "+ex.Message,"Run RECOVER on it or replace it.");}}}
  try{foreach(string f in Directory.EnumerateFiles(root,"*.*",SearchOption.AllDirectories)){string ext=Path.GetExtension(f);if(ext.Equals(".dwg",StringComparison.OrdinalIgnoreCase))continue;string rel=NamingService.Relative(f,root);if(rel.Split('\\').Any(seg=>NamingService.IsIgnoredFolder(seg,std)))continue;Add(rep,Severity.Info,"Library",kind.ToString(),f,"Stray non-drawing file in the library ("+ext+").","Delete it or move it out of the library.");}}catch{}
  say($"{rule.DisplayName} library: {count} drawing(s) under {root}{(o.Deep?$", {deep} opened":"")}");}
 static void AuditImages(AuditReport rep,AppSettings s,HashSet<string> referenced,Action<string> say){if(!Directory.Exists(s.ImagesFolder)){Add(rep,Severity.Error,"Menu","",s.ImagesFolder,"Icon images folder is missing.","Check IconMenuFolder and ImagesSubfolder in LSELIBRARYSETTINGS.");return;}int unused=0,total=0;
  foreach(string f in Directory.EnumerateFiles(s.ImagesFolder)){string ext=Path.GetExtension(f).ToLowerInvariant();if(ext is not(".png" or ".bmp" or ".jpg" or ".jpeg" or ".gif" or ".sld"))continue;total++;if(!referenced.Contains(Path.GetFullPath(f))){unused++;Add(rep,Severity.Info,"Menu","",f,"Icon image is not used by any checked icon menu entry.","Delete it, or reuse it from the Librarian.");}}
  say($"Icon images: {total} file(s), {unused} unused by the checked pages");}
 public static string WriteReport(AuditReport rep,string path){var x=new List<string>{"LSE Librarian audit"};x.AddRange(rep.Summary);x.Add("");foreach(var g in rep.Findings.GroupBy(f=>f.Severity).OrderBy(g=>g.Key)){x.Add($"=== {g.Key.ToString().ToUpperInvariant()} ({g.Count()}) ===");foreach(var f in g)x.Add($"{f.Severity}\t{f.Area}\t{f.Kind}\t{f.Path}\t{f.Message}\t{f.Suggestion}");x.Add("");}Directory.CreateDirectory(Path.GetDirectoryName(path)!);File.WriteAllLines(path,x);return path;}
}
